import {uid,seedState,memberName,canRead,createMeeting,sendMessage,delegate,extractDraft,validateItem,validationErrors,confirmMeeting,parseMemberFilter,makeICS,activateScheduled,getConfirmedEvents,syncConfirmedCalendar,updateDraftItem,removeDraftItem,restoreDraft,startScheduled,resumeConversation,setConfirmationMembers,disposeChild,createCorrection,setAgendaStatus,getPendingMessageCount,getConfirmationTargets,getMeetingBlockers,getAgendaItems,markMemberDeparted} from './domain.js';
import {createBrowserRepository} from './browser-repository.js';
import {renderCapsuleNavigation} from './capsule-ui.js';
import {createTutorial,advanceTutorial,renderTutorial} from './tutorial.js';
import {captureView,restoreView,clearComposer} from './ui-state.js';
import {createWorkflowActions} from './workflow-actions.js';
import {renderDesktop,renderAndroid,renderRoomList,groupAvatar} from './messenger-layouts.js';
import {addMessengerExamples} from './demo-conversations.js';
const designPreview=new URLSearchParams(location.search).has('designPreview');
const practice=new URLSearchParams(location.search).has('practice');
const practiceSeed=()=>{const s=seedState();s.meetings=[];s.calendar=[];s.notifications=[];s.organization='ITDA 연습 공간';s.tutorial=createTutorial();return s;};
const repo=await createBrowserRepository({storage:{getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v)},indexedDB:globalThis.indexedDB,memory:designPreview,dbName:practice?'itda-practice-v3':'itda-capsules-v3',legacyKey:practice?'itda.practice.legacy':'itda.capsules.v2',seed:practice?practiceSeed:seedState});
let state=repo.get();
if(repo.status.kind==='ready'){
 const changed=!practice&&addMessengerExamples(state);
 if(syncConfirmedCalendar(state)||changed)await repo.save();
}
const requested=new URLSearchParams(location.search).get('capsule');
let activeId=requested&&state.meetings.some(m=>m.id===requested)?requested:state.meetings[0]?.id;
let page='meeting',view='chat',search='',month=new Date(new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Seoul'})+'T12:00:00+09:00'),mobileMenu=false;
const isAndroidRoute=location.pathname.startsWith('/android');
const mobileQuery=window.matchMedia('(max-width: 700px)');
let mobileScreen=requested?'room':'list',listFilter='all',listSearch='',searchOpen=false;
function useAndroid(){return isAndroidRoute||mobileQuery.matches;}
let delegationSelection=new Set(),delegationMembers=new Set(),creationMembers=new Set(),memberFilter='',focusedSource=null;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const meeting=()=>state.meetings.find(m=>m.id===activeId);
const person=id=>state.members.find(m=>m.id===id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={link:'<rect x="3" y="6" width="12" height="7" rx="3.5" transform="rotate(-35 9 9.5)"/><rect x="9" y="11" width="12" height="7" rx="3.5" transform="rotate(-35 15 14.5)"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H7l-4 3V11a9 9 0 0 1 18 0Z"/><path d="M7 9h10M7 13h6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h2m3 0h2"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-17a3 3 0 0 1 0 6m2 11v-3a6 6 0 0 0-3-5"/>',archive:'<rect x="3" y="3" width="18" height="5" rx="1"/><path d="M5 8v13h14V8m-10 5h6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',branch:'<path d="M6 3v10a4 4 0 0 0 4 4h10m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',file:'<path d="M14 2H5v20h14V7ZM14 2v6h5M8 12h8m-8 4h6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m14 5-7 7 7 7"/>',external:'<path d="M14 3h7v7m-9 2 9-9M10 3H3v18h18v-7"/>',bell:'<path d="M5 9a7 7 0 0 1 14 0v6l2 3H3l2-3Zm5 13h4"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',edit:'<path d="m15 3 6 6-12 12H3v-6Zm-2 2 6 6"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Zm-4 10 3 3 5-6"/>'};
Object.assign(icons,{phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4M10 5h4"/>',settings:'<path d="m10 2-1 3-3 1-3-1-2 4 2 2v3l-2 2 2 4 3-1 3 1 1 3h4l1-3 3-1 3 1 2-4-2-2v-3l2-2-2-4-3 1-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',more:'<circle cx="4" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="20" cy="12" r="1.5"/>', 'plus-chat':'<path d="M20 11a8 8 0 0 0-8-8 8 8 0 0 0-8 8v8l4-2h4m6-5v9m-4-4h9"/>'});
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.chat}</svg>`;
const btn=(action,label,cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const avatar=(id,size='')=>{const p=person(id);return `<span class="avatar ${p?.color||'blue'} ${size}" title="${esc(p?.name)}">${esc(p?.name?.slice(-2,-1)||'?')}</span>`;};
const date=value=>new Date(value).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false});
const day=value=>new Date(value).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric'});
const time=value=>new Date(value).toLocaleTimeString('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false});
const labels={open:'대화 중',review:'공동 확인',confirmed:'확정됨',scheduled:'예약됨',deferred:'보류·이관',cancelled:'취소됨'};
function toast(text){if(modal.open){let feedback=modal.querySelector('.modal-feedback');if(!feedback){feedback=document.createElement('p');feedback.className='modal-feedback';feedback.setAttribute('role','status');modal.querySelector('.modal-body').append(feedback);}feedback.textContent=text;}const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4000);}
let actionBusy=false;
function requireSaved(){if(repo.status.kind!=='ready')throw Error('먼저 저장을 재시도하거나 현재 작업을 내보낸 뒤 복구해주세요.');}
async function persist(){const result=await repo.save();renderStorage();if(!result.ok&&modal.open){const body=modal.querySelector('.modal-body');if(!body.querySelector('.recovery-controls')){const controls=document.createElement('div');controls.className='recovery-controls';controls.innerHTML=btn('storage-export','현재 내용 내보내기','outline')+btn('storage-retry','다시 저장','outline')+btn('close','닫기','outline');body.append(controls);}}if(!result.ok)throw Error(result.message||'저장하지 못했어요. 입력을 보존했으니 재시도하거나 내보내주세요.');return result;}
function markRead(m){if(m&&canRead(m,state.profileId)){state.reads??={};state.reads[`${state.profileId}:${m.id}`]=m.messages.length;}}
function tutorialEvent(event,id=activeId){if(practice)state.tutorial=advanceTutorial(state.tutorial||createTutorial(),event,{meetingId:id});}
function renderStorage(){const el=document.querySelector('#storage-status');if(!el)return;const status=repo.status;el.hidden=status.kind==='ready';el.innerHTML=el.hidden?'':`<strong>저장 상태: ${esc(status.message||status.kind)}</strong><span>현재 입력은 이 화면에 보존됩니다.</span>${btn('storage-export','현재 내용 내보내기','outline')}${btn('storage-original','원본 내보내기','outline')}${status.kind==='conflict'?btn('storage-reload','최신 저장본 불러오기','outline'):btn('storage-retry','다시 저장','outline')}${btn('storage-recovery','복구 옵션','outline')}`;}
function selectMeeting(id,which='chat'){const enter=mobileScreen!=='room'||activeId!==id;activeId=id;page='meeting';view=which;search='';mobileMenu=false;mobileScreen='room';markRead(meeting());const url=new URL(location.href);url.searchParams.set('capsule',id);if(useAndroid()&&enter)history.pushState({screen:'room'},'',url);else history.replaceState(null,'',url);}
function childMeetings(m){return state.meetings.filter(c=>c.parentId===m.id);}
function empty(title,body,action=''){return `<div class="empty-state"><div class="empty-icon">${icon('link')}</div><h3>${title}</h3><p>${body}</p>${action}</div>`;}
function layoutContext(){const m=meeting();return {state,activeId,page,listFilter,listSearch,searchOpen,mobileScreen,esc,icon,btn,avatar,canRead,roomContent:m?renderMeeting(m):empty('새로운 이야기를 시작해보세요','함께할 멤버를 골라 첫 캡슐을 열어보세요.',btn('create','새 캡슐 만들기','primary')),workspaceContent:page==='calendar'?renderCalendar():page==='archive'?renderArchive():page==='members'?renderMembers():''};}
function render(){
 captureView(activeId);
 document.body.classList.toggle('is-android',useAndroid());
 document.body.classList.toggle('dedicated-android',isAndroidRoute);
 const ctx=layoutContext();app.innerHTML=useAndroid()?renderAndroid(ctx):renderDesktop(ctx);
 const tutorial=document.querySelector('#tutorial-host');tutorial.innerHTML=renderTutorial(state.tutorial||createTutorial(),state,{practice});
 restoreView(activeId);renderStorage();
}
function renderMeeting(m){
 const access=canRead(m,state.profileId);
 const header=`<header class="room-header">${btn('room-back',icon('back'),'room-back','aria-label="캡슐 목록으로 돌아가기"')}${groupAvatar(m,{state,esc})}<div class="room-heading"><h1>${esc(m.title)}</h1><p>${esc(state.organization)} · ${labels[m.status]}</p></div><div class="room-header-actions">${btn('room-info',icon('menu'),'icon-button','aria-label="캡슐 정보"')}</div></header>`;
 const navigation=renderCapsuleNavigation(state,m,{view,errorCount:validationErrors(state,m).length})+(!useAndroid()&&access&&m.draft?`<div class="split-toggle">${btn('view','대화와 결론 나란히 보기','text-button','data-view="split"')}</div>`:'');
 const content=!access?empty('담당 멤버만 볼 수 있는 캡슐이에요','확정된 결론은 상위 캡슐에서 볼 수 있어요.'):view==='split'&&!useAndroid()?`<div class="capsule-split"><div class="split-conversation">${renderChat(m)}</div><div class="split-minutes">${renderMinutes(m)}</div></div>`:view==='chat'?renderChat(m):view==='minutes'||view==='split'?renderMinutes(m):renderResult(m);
 return `<section class="chat-room ${view==='chat'?'chat-view':'record-view'}">${header}${navigation}${content}</section>`;
}
function renderChat(m){
 const messages=m.messages.filter(x=>x.text.toLowerCase().includes(search.toLowerCase()));
 return `<div class="conversation-header"><div><span class="live-dot ${m.status==='open'?'':'off'}"></span><strong>${m.status==='open'?'우리의 이야기가 이어지고 있어요':m.status==='review'?'대화를 모아 함께 확인하고 있어요':m.status==='scheduled'?'다음 만남을 기다리고 있어요':'모두가 확인한 기록으로 남았어요'}</strong></div><label class="message-search">${icon('search')}<input id="message-search" aria-label="대화 검색" placeholder="대화 검색" value="${esc(search)}"></label></div>${m.carryover.length?`<div class="carryover-banner">${icon('archive')}<div><strong>지난 회의에서 이어진 미결 안건 ${m.carryover.length}건</strong>${m.carryover.map(i=>`<p>• ${esc(i.text)}</p>`).join('')}</div></div>`:''}<div id="messages" class="messages" aria-label="캡슐 대화"><div class="chat-date"><span>${m.messages.length?day(m.messages[0].createdAt):'새로운 이야기의 시작'}</span></div>${m.sourceMessages.length?`<details class="source-context"><summary>${icon('branch')} 상위 회의에서 가져온 대화 ${m.sourceMessages.length}개 ${icon('chevron')}</summary>${m.sourceMessages.map(x=>`<div><strong>${esc(memberName(state,x.authorId))}</strong><p>${esc(x.text)}</p></div>`).join('')}</details>`:''}${messages.map(x=>renderMessage(x,m)).join('')}${search&&!messages.length?empty('검색 결과가 없어요','다른 단어로 찾아보세요.'):!messages.length?empty('이 캡슐의 첫 이야기를 남겨주세요','안건을 함께 나누고 결론을 정리해보세요.'):''}${!search?childMeetings(m).map(c=>renderChildCard(c)).join(''):''}${!search?m.conclusions.filter(c=>!childMeetings(m).some(ch=>ch.id===c.meetingId)).map(c=>renderConclusion(c)).join(''):''}</div>${['open','review'].includes(m.status)?`<div class="chat-bottom"><div class="chat-hint">${icon('shield')} 메시지는 참여자에게만 보여요.${practice?btn('practice-example','연습 예문 채우기','text-button'):''}</div><form id="composer" class="composer"><textarea name="message" aria-label="메시지 입력" placeholder="${m.parentId?'집중해서 논의할 내용을 남겨주세요':'메시지를 입력하고, 우리의 다음을 이어가요…'}" rows="2" maxlength="4000" required></textarea><div><span>Enter 전송 <b>·</b> Shift + Enter 줄바꿈</span><div>${btn('delegate',icon('branch')+' 하위 캡슐','composer-delegate')}<button class="send-button" aria-label="메시지 보내기">${icon('arrow')}</button></div></div></form><div class="chat-bottom-actions">${btn('draft',icon('spark')+(m.draft?' 새 대화 반영':' 결론 초안 만들기'),'text-button')}${practice?btn('practice-example','연습 예문 넣기','outline'):'<span>근거가 연결되는 결론</span>'}</div></div>`:m.status==='scheduled'?`<div class="closed-bar"><span>${icon('clock')} ${date(m.startsAt)}에 시작 예정</span>${btn('start-scheduled','지금 시작하기','primary')}</div>`:`<div class="closed-bar"><span>${icon(m.status==='confirmed'?'check':'file')} ${m.status==='confirmed'?'확정된 회의는 읽기 전용이에요.':'대화를 바탕으로 초안이 준비됐어요.'}</span>${btn('view',m.status==='confirmed'?'확정 기록 보기':'회의록 확인하기','primary','data-view="minutes"')}${m.status==='review'?btn('reopen','대화 이어가기','quiet'):''}</div>`}`;
}
function renderMessage(x,m){return `<article class="message ${x.authorId===state.profileId?'own':''}" id="message-${esc(x.id)}">${avatar(x.authorId)}<div class="message-content"><div class="message-meta"><strong>${esc(memberName(state,x.authorId))}</strong><time>${time(x.createdAt)}</time>${['open','review'].includes(m.status)?btn('delegate',icon('branch'),'message-delegate',`data-anchor="${esc(x.id)}" aria-label="이 대화부터 하위 캡슐로 분리" title="하위 캡슐로 분리"`):''}</div><div class="message-bubble">${esc(x.text)}</div></div></article>`;}
function renderConclusion(c){return `<div class="child-card result-child"><div class="child-card-label">${icon('check')} 하위 캡슐 결과 도착</div><h3>${esc(c.title)}</h3>${c.decisions.map(t=>`<p><b>결정</b> ${esc(t)}</p>`).join('')}${c.tasks.map(t=>`<p><b>할 일</b> ${esc(t.text)} · ${esc(memberName(state,t.ownerId))} · ${day(t.dueAt)}</p>`).join('')}<small>참여자 확인 ${c.memberIds.length}/${c.memberIds.length} · 최종 회의록에 합산</small></div>`;}
function renderChildCard(c){const result=meeting().conclusions.find(r=>r.meetingId===c.id);return `<div class="child-wrapper">${result?renderConclusion(result):`<div class="child-card"><div class="child-card-label">${icon('branch')} 하위 캡슐 열림 <span class="status-badge ${c.status}">${labels[c.status]}</span></div><h3>${esc(c.title)}</h3><p>${c.memberIds.map(id=>esc(memberName(state,id))).join(' · ')} <span>· 원문은 참여자만</span></p></div>`}${btn('open',canRead(c,state.profileId)?'하위 캡슐 열기 '+icon('arrow'):'담당 멤버만 원문 열람 '+icon('shield'),'child-open',`data-id="${c.id}"`)}</div>`;}
function renderMinutes(m){
 if(!m.draft)return `<div class="minutes-scroll">${empty('대화에서 결론을 모아보세요','결정·할 일·미결·일정을 근거와 함께 정리해요.',m.status==='open'?btn('draft','결론 초안 만들기','primary'):'')}<details class="format-guide"><summary>초안에 모이는 대화 형식</summary><p>결정: 함께 정한 내용<br>할 일: 준비할 일 | 담당자 이름 | 내일 18:00<br>미결: 다음에 정할 내용<br>다음 회의: 후속 논의 | 내일 19:00 | 온라인 | 전원</p></details></div>`;
 const errors=validationErrors(state,m),confirmed=m.status==='confirmed',editable=m.status==='review',targets=getConfirmationTargets(m);
 const superseding=state.meetings.find(x=>x.correctionOf===m.id&&x.status==='confirmed');
 const latest=m.draftHistory?.at(-1);
 const history=(m.draftHistory||[]).slice().reverse();
 const changes=latest?['decisions','tasks','unresolved','events'].flatMap(type=>{const before=latest.draft[type]||[],after=m.draft[type];return [...before.filter(x=>!after.some(y=>y.id===x.id)).map(x=>'제외: '+x.text),...after.filter(x=>!before.some(y=>y.id===x.id&&JSON.stringify(y)===JSON.stringify(x))).map(x=>'변경/추가: '+x.text)];}):[];
 return `<div class="minutes-scroll"><div class="section-heading"><div><div class="eyebrow">CAPSULE · VERSION ${m.revision}</div><h2>${confirmed?'함께 확인한 결론':'결론 검토'}</h2></div>${history.length?btn('draft-history','버전 이력','outline'):''}</div>
 ${superseding?`<div class="validation-notice">정정된 최신 결론이 있어요. ${btn('open','최신 정정본 열기','outline',`data-id="${superseding.id}" data-view="minutes"`)}</div>`:''}
 ${m.correctionOf?`<div class="validation-notice">정정 사유: ${esc(m.correctionReason)} ${btn('open','원본 보기','outline',`data-id="${m.correctionOf}" data-view="minutes"`)}<p>이미 열린 다음 캡슐은 자동 변경하지 않아요. ${(m.correctionImpacts||[]).map(x=>esc(state.meetings.find(y=>y.id===x.meetingId)?.title||'')).join(' · ')}</p></div>`:''}
 <div class="confirmation-banner ${confirmed?'complete':''}"><div><strong>확인 대상 ${m.confirmations.length}/${targets.length}명 · 버전 ${m.revision}</strong><p>${confirmed?'이 버전의 확인 기록을 보존했어요.':'실제 내용이 바뀌면 변경점을 확인하고 다시 확인해요. 대화는 계속할 수 있어요.'}</p></div></div>
 ${getPendingMessageCount(m)?`<div class="validation-notice">새 대화 ${getPendingMessageCount(m)}개가 아직 반영되지 않았어요. ${btn('draft','새 대화 반영','outline')}</div>`:''}
 ${changes.length?`<details class="change-summary" open><summary>직전 버전에서 바뀐 내용 ${changes.length}건</summary><ul>${changes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}
 ${errors.length?`<div class="validation-notice">확인 필요 ${errors.length}건 · 아래 근거와 담당·날짜를 보완해주세요.</div>`:''}
 ${[['decisions','결정'],['tasks','할 일'],['events','일정 · 다음 캡슐']].map(([type,label])=>`<section class="minutes-group"><h3>${label} <small>${m.draft[type].length}</small>${editable?btn('add-item','추가','text-button',`data-type="${type}"`):''}</h3>${m.draft[type].map(item=>renderMinuteItem(m,item,type)).join('')||'<p class="nothing">아직 모인 항목이 없어요.</p>'}</section>`).join('')}
 <section class="minutes-group"><h3>미결 안건 · 이어갈 일 ${editable?btn('add-item','추가','text-button','data-type="unresolved"'):''}</h3>${getAgendaItems(m).map(item=>`<article class="minute-item"><div><p>${esc(item.text)}</p><small>${({open:'다음으로 유지',resolved:'해결됨',deferred:'보류'})[item.status]} · 출처 ${esc(state.meetings.find(x=>x.id===item.from)?.title||'이전 캡슐')}</small>${item.reason?`<p>${esc(item.reason)}</p>`:''}</div>${editable?btn('agenda','상태·승계 지정','outline',`data-id="${esc(item.id)}"`):''}</article>`).join('')||'<p class="nothing">미결 안건이 없어요.</p>'}</section>
 ${m.conclusions.length?`<section class="minutes-group"><h3>합류한 하위 결론</h3>${m.conclusions.map(renderConclusion).join('')}</section>`:''}
 ${renderPolicyHistory(m)}<p class="minutes-policy">근거가 결론을 뒷받침하는지는 참여자가 확인해주세요.</p></div>
 <div class="review-footer"><p>${confirmed?'확정 기록':esc(getMeetingBlockers(state,m).join(' · ')||'확인할 준비가 됐어요.')}</p><div>${confirmed?btn('correction','정정본 만들기','outline')+btn('view','확정 일정','primary','data-view="result"'):editable?btn('confirm',m.confirmations.includes(state.profileId)?'내 확인 완료':'이 버전 확인','primary',`data-revision="${m.revision}" ${m.confirmations.includes(state.profileId)||!targets.includes(state.profileId)?'disabled':''}`):''}</div></div>`;
}
function renderPolicyHistory(m){return (m.policyHistory||[]).length?`<details class="policy-history"><summary>참여·보류·변경 기록 ${(m.policyHistory||[]).length}건</summary>${m.policyHistory.map(x=>`<p><strong>${esc(memberName(state,x.actorId))}</strong> · ${esc(x.kind)} · ${esc(x.reason)}${x.memberIds?` · 확인 대상: ${x.memberIds.map(id=>esc(memberName(state,id))).join(', ')}`:''}</p>`).join('')}</details>`:'';}
function renderMinuteItem(m,item,type){const issues=validateItem(state,m,item,type);return `<article class="minute-item ${issues.length?'needs-review':''}"><div class="minute-item-content"><p>${esc(item.text)}</p>${type==='tasks'?`<div class="item-meta"><span>${item.ownerId?esc(memberName(state,item.ownerId)):'담당 확인 필요'}</span><span>${item.dueAt?day(item.dueAt):'마감 확인 필요'}</span></div>`:type==='events'?`<div class="item-meta"><span>${item.at?date(item.at):'날짜·시간 확인 필요'}</span><span>${esc(item.location||'장소 미정')}</span><span>${item.participantIds.length}명</span>${item.kind==='next'?'<b>다음 캡슐 예약</b>':''}</div>`:''}<div class="evidence-row">${btn('evidence',icon('link')+` 근거 메시지 ${item.evidenceIds.length}`,'evidence-button',`data-type="${type}" data-id="${item.id}"`)}${issues.length?`<span class="needs-label">${esc(issues.join(' · '))}</span>`:'<span class="valid-label">✓ 코드 검사 통과</span>'}</div></div>${m.status==='review'?btn('edit-item',icon('edit'),'icon-button item-edit',`data-type="${type}" data-id="${item.id}" aria-label="${esc(item.text)} 수정"`):''}</article>`;}
function renderResult(m){
 if(m.status!=='confirmed')return `<div class="minutes-scroll">${empty('아직 이 채팅방에서 확정한 일정이 없어요','이 방의 회의록을 모두 확인하면 확정 일정이 이곳에 저장돼요.',btn('view','회의록 확인하기 '+icon('arrow'),'primary','data-view="minutes"'))}</div>`;
 const events=getConfirmedEvents(state,state.profileId,m.id),next=state.meetings.filter(n=>n.previousId===m.id);
 return `<div class="minutes-scroll"><div class="section-heading"><div><div class="eyebrow">THIS CHAT ONLY</div><h2>이 채팅방의 확정 일정</h2></div><span class="confirmed-seal">${icon('check')} 확정</span></div><div class="confirmation-banner complete">${icon('check')}<div><strong>참여자 ${m.confirmations.length}/${getConfirmationTargets(m).length}명 확인 · 확정됨</strong><p>${esc(m.title)}에서 확정한 내용만 보여요.</p></div></div>${m.parentId?`<div class="room-scope-note">확정 결론은 상위 회의에 합류했어요. 이 방의 일정은 별도로 보관해요.</div>`:''}<div class="result-calendar">${calendarGrid(events)}</div><h3 class="result-heading">이 방에서 확정한 일정 <small>${events.length}</small></h3>${events.map(renderEvent).join('')||'<p class="nothing">이 채팅방에서 확정한 일정은 없어요.</p>'}${next.map(n=>`<div class="next-meeting-card"><span>${icon('clock')} 다음 캡슐 예약됨</span><h3>${esc(n.title)}</h3><p>${date(n.startsAt)} · 참여자 ${n.memberIds.length}명</p><div class="carryover-count">미결 ${n.carryover.length}건 고정 · 하위 결론 ${n.conclusions.length}건 이어짐</div>${btn('open','다음 캡슐 미리 보기 '+icon('arrow'),'outline',`data-id="${n.id}"`)}</div>`).join('')}<div class="room-scope-note">다른 채팅방의 확정 일정은 앱 기본 화면의 캘린더에서 모아볼 수 있어요.</div></div><div class="result-footer">${btn('share',icon('external')+' 결과 카드 공유하기','primary')}<small>기기 공유 또는 복사 · 카카오 SDK 미연결</small></div>`;
}
function calendarGrid(events){const year=month.getUTCFullYear(),mo=month.getUTCMonth(),first=new Date(Date.UTC(year,mo,1)).getUTCDay(),days=new Date(Date.UTC(year,mo+1,0)).getUTCDate();return `<div class="calendar-head"><h3>${year}년 ${mo+1}월</h3><div>${btn('month',icon('back'),'icon-button','data-offset="-1" aria-label="이전 달"')}${btn('month',icon('chevron'),'icon-button','data-offset="1" aria-label="다음 달"')}</div></div><div class="calendar-grid">${'일월화수목금토'.split('').map(d=>`<span class="weekday">${d}</span>`).join('')}${Array.from({length:first},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{const key=`${year}-${String(mo+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;const dates=events.filter(e=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul'}).format(new Date(e.at))===key);return `<span class="calendar-day ${dates.length?'has-event':''}" title="${esc(dates.map(e=>e.text).join(', '))}">${i+1}${dates.length?'<i></i>':''}</span>`;}).join('')}</div>`;}
function renderEvent(e){return `<article class="event-card"><div class="event-date"><small>${new Date(e.at).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul',month:'long'})}</small><strong>${new Date(e.at).toLocaleDateString('en-US',{timeZone:'Asia/Seoul',day:'numeric'})}</strong></div><div class="event-body"><div class="event-source">${esc(state.meetings.find(m=>m.id===e.meetingId)?.title||"채팅방")}</div><h3>${esc(e.text)} ${e.kind==='next'?'<span class="tiny-tag">다음 회의</span>':''}</h3><p>${date(e.at)} · ${esc(e.location||'장소 미정')}</p><div class="event-participants">${icon('users')} ${e.participantIds.map(id=>esc(memberName(state,id))).join(' · ')}</div><div class="event-actions">${btn('google',icon('external')+' 구글 캘린더에 추가','outline',`data-id="${e.id}"`)}${btn('ics',icon('download')+' .ics 받기','outline',`data-id="${e.id}"`)}</div></div></article>`;}
function renderCalendar(){const events=getConfirmedEvents(state,state.profileId);const monthEvents=events.filter(e=>{const d=new Date(Date.parse(e.at)+9*3600000);return d.getUTCFullYear()===month.getUTCFullYear()&&d.getUTCMonth()===month.getUTCMonth();});return `<div class="workspace-page"><div class="workspace-intro"><div class="eyebrow">OUR NEXT MOMENTS</div><h1>확정한 약속이 모이는 곳</h1><p>내가 참여한 모든 채팅방에서 확정한 일정을 모아 보여줘요.</p></div><div class="calendar-layout"><section class="surface calendar-large">${calendarGrid(events)}</section><section><div class="section-heading"><h2>${month.getUTCMonth()+1}월의 약속</h2><span class="tiny-tag">${monthEvents.length}개 일정</span></div>${monthEvents.map(renderEvent).join('')||empty('아직 확정된 일정이 없어요','회의록을 함께 확정하면 이곳에 자동으로 등록돼요.',btn('workspace','캡슐로 돌아가기','outline','data-page="meeting"'))}</section></div></div>`;}
function renderArchive(){const items=state.meetings.filter(m=>m.status==='confirmed'&&canRead(m,state.profileId));return `<div class="workspace-page"><div class="workspace-intro"><div class="eyebrow">DECISIONS THAT STAY</div><h1>우리의 결정은 여기 남아요</h1><p>참여자 모두가 확인한 공식 회의 기록이에요.</p></div><div class="archive-grid">${items.map(m=>`<article class="archive-card"><span class="status-badge confirmed">${icon('check')} 확정됨</span><h2>${esc(m.title)}</h2><p>${date(m.confirmedAt)} · ${m.memberIds.length}명 참여</p><div><span>결정 <b>${m.draft.decisions.length}</b></span><span>할 일 <b>${m.draft.tasks.length}</b></span><span>미결 <b>${m.draft.unresolved.length}</b></span></div>${btn('open','확정 기록 보기 '+icon('arrow'),'outline',`data-id="${m.id}" data-view="minutes"`)}</article>`).join('')||empty('첫 번째 결정을 기다리고 있어요','캡슐에서 회의록을 확인하고 함께 확정해보세요.')}</div></div>`;}
function renderMembers(){return `<div class="workspace-page"><div class="workspace-intro"><div class="eyebrow">BETTER DECISIONS, TOGETHER</div><h1>함께 다음을 만드는 사람들</h1><p>${esc(state.organization)} · 시연용 가상 멤버 ${state.members.length}명</p></div><div class="members-grid">${state.members.map(p=>`<article class="member-card">${avatar(p.id,'large')}<h2>${esc(p.name)} ${p.id===state.profileId?'<small>현재 시연 중</small>':''}</h2><p>${p.role} · ${p.grade}학년</p><div>${p.teams.map(t=>'<span>'+esc(t)+'</span>').join('')}</div>${btn('switch-profile','이 멤버로 시연하기','outline',`data-id="${p.id}"`)}</article>`).join('')}</div><p class="privacy-note">${icon('shield')} 실제 서비스에서는 서버에서 로그인과 멤버별 접근 권한을 검사해요. 이 데모의 참여자 전환은 화면 흐름 체험용입니다.</p></div>`;}
function openModal(title,body,footer='',wide=false){modal.className=wide?'wide':'';modal.innerHTML=`<div class="modal-header"><div><span class="eyebrow">ITDA · CAPSULE</span><h2>${title}</h2></div>${btn('close',icon('close'),'icon-button','aria-label="닫기"')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal();}
const field=(label,name,value='',type='text',attrs='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
function createDialog(){memberFilter='';creationMembers=new Set(practice?[state.profileId,'jieun']:[state.profileId]);creationMembers.add(state.profileId);openModal('새 캡슐 만들기',`<form id="create-form">${field('안건','title','', 'text','placeholder="어떤 결정을 함께 내릴까요?" maxlength="100" required')}${field('회의 소개 (선택)','description','','text','placeholder="이 회의에서 나눌 이야기를 적어주세요" maxlength="250"')}<label class="field"><span>누구와 회의할까요?</span><div class="ai-input">${icon('spark')}<input id="member-filter" name="filter" value="${memberFilter}" placeholder="예: 축제 준비팀 중 2학년" autocomplete="off"></div></label><div id="member-filter-results">${renderMemberFilter()}</div><p class="form-note">문장을 팀·학년 조건으로 바꾸는 로컬 규칙 시연이에요. 이름을 직접 선택할 수도 있어요.</p></form>`,`<span class="footer-note">새로운 결정의 시작</span><button type="submit" form="create-form" class="primary" id="create-submit">${creationMembers.size}명과 회의 시작 ${icon('arrow')}</button>`);}
function renderMemberFilter(){const filter=parseMemberFilter(memberFilter,state.members);return `<div class="filter-chips">${filter.team?`<span>팀: ${esc(filter.team)}</span>`:''}${filter.grade?`<span>학년: ${filter.grade}</span>`:''}${!filter.team&&!filter.grade?'<span>직접 멤버 선택</span>':''}${btn('clear-filter','전체 보기','text-button')}</div>${filter.unrecognized?'<div class="filter-warning">인식하지 못한 조건이에요. 팀·학년을 다시 입력하거나 아래에서 직접 선택해주세요.</div>':''}<div class="form-section-label">추천 멤버 ${filter.members.length}명 <span>현재 참여자는 자동 포함</span></div><div class="member-options">${state.members.map(p=>`<label class="member-option ${filter.members.some(x=>x.id===p.id)?'recommended':''}">${avatar(p.id,'small')}<span>${p.name}<small>${p.grade}학년 · ${p.teams.join(' · ')}</small></span><input type="checkbox" name="create-member" value="${p.id}" ${creationMembers.has(p.id)?'checked':''} ${p.id===state.profileId?'disabled':''}></label>`).join('')}</div>`;}
function delegateDialog(anchor){const m=meeting();if(!canRead(m,state.profileId))throw Error('참여자만 위임할 수 있어요.');if(!['open','review'].includes(m.status))throw Error('진행 중인 캡슐에서 위임할 수 있어요.');if(!m.messages.length)throw Error('먼저 넘길 대화를 남겨주세요.');const all=m.messages;delegationSelection=new Set(anchor?[anchor]:[]);delegationMembers=new Set();
openModal(icon('branch')+' 하위 캡슐로 분리',`<form id="delegate-form">${field('집중해서 논의할 안건','title','','text','required maxlength="100"')}<p class="form-note">직전 대화에서 필요한 메시지만 골라 넘겨주세요.<br>메인 회의는 멈추지 않고, 확정된 결론만 돌아와요.</p><div class="form-section-label">넘길 대화 <span id="selected-message-count">${delegationSelection.size}개 선택</span></div><div class="message-choices">${all.map(x=>`<label class="message-choice"><input type="checkbox" name="delegate-message" value="${x.id}" ${delegationSelection.has(x.id)?'checked':''}><span><small>${esc(memberName(state,x.authorId))}</small>${esc(x.text)}</span></label>`).join('')}</div><div class="form-section-label">담당 멤버 <span>상위 참여자 중에서 선택</span></div><div class="delegate-members">${m.memberIds.map(id=>`<label><input type="checkbox" name="delegate-member" value="${id}" ${delegationMembers.has(id)?'checked':''}>${avatar(id,'small')}<span>${esc(memberName(state,id))}</span></label>`).join('')}</div><div class="privacy-callout">${icon('shield')} 하위 원문은 담당 멤버에게만, 결론은 상위 회의로.</div></form>`,`<button type="submit" form="delegate-form" class="primary full-width">하위 캡슐 열고 위임하기 ${icon('arrow')}</button>`,true);}
function evidenceDialog(type,id){const m=meeting();const item=m.draft[type].find(i=>i.id===id);const sources=[...m.messages,...m.sourceMessages];openModal('결정의 근거를 확인해요',`<p class="form-note">${esc(item.text)}</p><div class="evidence-messages">${item.evidenceIds.map(mid=>{const source=sources.find(x=>x.id===mid);return source?`<article>${avatar(source.authorId)}<div><strong>${esc(memberName(state,source.authorId))}<time>${date(source.createdAt)}</time></strong><p>${esc(source.text)}</p><small>메시지 ID · ${esc(source.id)}</small></div></article>`:'<p class="needs-label">원문을 찾을 수 없어요. 근거를 다시 선택해주세요.</p>';}).join('')||'<p class="needs-label">연결된 근거가 없어요.</p>'}</div><div class="privacy-callout">${icon('shield')} 실제 대화가 결론을 뒷받침하는지 직접 확인해주세요.</div>`,btn('close','확인했어요','primary'));}
function editItemDialog(type,id){const m=meeting();if(m.status!=='review')throw Error('검토 중인 회의록만 수정할 수 있어요.');const item=m.draft[type].find(i=>i.id===id)||{id:uid(),text:'',evidenceIds:[],ownerId:'',dueAt:null,at:null,location:'',participantIds:[],kind:'event'};focusedSource={type,itemId:item.id,isNew:!id,revision:m.revision};const dateLocal=value=>value?new Date(Date.parse(value)+9*3600000).toISOString().slice(0,16):'';
openModal(({decisions:'결정',tasks:'할 일',unresolved:'미결 안건',events:'일정'})[type]+' 수정',`<form id="item-form">${field('내용','text',item.text,'text','required maxlength="500"')}${type==='tasks'?`<label class="field"><span>담당 멤버</span><select name="ownerId" required><option value="">담당자를 선택해주세요</option>${m.memberIds.map(id=>`<option value="${id}" ${item.ownerId===id?'selected':''}>${esc(memberName(state,id))}</option>`).join('')}</select></label>${field('마감 일시 (한국 시간)','dueAt',dateLocal(item.dueAt),'datetime-local','required')}`:''}${type==='events'?`${field('시작 일시 (한국 시간)','at',dateLocal(item.at),'datetime-local','required')}${field('장소','location',item.location,'text','maxlength="150"')}<label class="field"><span>일정 유형</span><select name="kind"><option value="event">일반 일정</option><option value="next" ${item.kind==='next'?'selected':''}>다음 회의 · 캡슐 자동 예약</option></select></label><div class="form-section-label">일정 참여자</div><div class="delegate-members">${m.memberIds.map(id=>`<label><input type="checkbox" name="event-member" value="${id}" ${item.participantIds.includes(id)?'checked':''}><span>${esc(memberName(state,id))}</span></label>`).join('')}</div>`:''}<div class="form-section-label">근거 메시지 <span>최소 1개 선택</span></div><div class="message-choices evidence-choices">${[...m.sourceMessages,...m.messages].map(x=>`<label class="message-choice"><input type="checkbox" name="evidence" value="${x.id}" ${item.evidenceIds.includes(x.id)?'checked':''}><span><small>${esc(memberName(state,x.authorId))}</small>${esc(x.text)}</span></label>`).join('')||'<p class="muted">근거로 연결할 대화가 없어요. 대화를 먼저 남겨주세요.</p>'}</div><p class="form-note">실제 내용이 바뀌면 다시 확인해요. 동일 내용 저장은 이전 확인을 유지해요.</p></form>`,`${id&&type!=='unresolved'?btn('delete-item','항목 제외','danger',`data-type="${type}" data-id="${id}"`):btn('close','취소','quiet')}<button form="item-form" type="submit" class="primary">수정 저장하기</button>`,true);}
function shareText(m){return `[잇다 · 확정 회의록] ${m.title}\n참여자 ${m.confirmations.length}/${getConfirmationTargets(m).length}명 확인\n\n${[['decisions','결정'],['tasks','할 일'],['unresolved','미결']].map(([type,label])=>m.draft[type].length?`${label}\n${m.draft[type].map(x=>'• '+x.text+(type==='tasks'?` · ${memberName(state,x.ownerId)} · ${day(x.dueAt)}`:'')).join('\n')}`:'').filter(Boolean).join('\n\n')}\n${m.conclusions.map(c=>'하위 결론 · '+c.title+'\n'+c.decisions.join('\n')).join('\n')}\n${state.calendar.filter(e=>e.meetingId===m.id).map(e=>'일정 · '+e.text+' · '+date(e.at)).join('\n')}`;}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('복사했어요. 원하는 대화방에 붙여넣어주세요.');}catch{openModal('직접 복사해주세요',`<label class="field"><span>복사할 내용</span><textarea readonly rows="10">${esc(text)}</textarea></label>`,btn('close','닫기','primary'));}}
function inviteDialog(){const url=new URL(location.href);url.search='';url.searchParams.set('capsule',activeId);openModal('링크 하나로, 회의를 이어가요',`<p class="form-note">앱 설치 없이 캡슐에 들어오는 흐름이에요.</p><label class="field"><span>이 캡슐의 링크</span><input id="invite-url" readonly value="${esc(url.href)}"></label><div class="privacy-callout">${icon('shield')} 로컬 데모 링크예요. 같은 브라우저의 저장된 회의만 열려요. 다른 기기에서 참여하려면 서버 연결이 필요해요.</div>`,btn('copy-invite',icon('link')+' 링크 복사하기','primary'));}
function settingsDialog(){openModal('더보기 · 설정',`<div class="settings-profile">${avatar(state.profileId)}<div><strong>${esc(memberName(state,state.profileId))}</strong><p>${esc(state.organization)} · 시연 참여자</p></div></div><label class="field settings-select"><span>시연 참여자 전환</span><select id="profile-select" aria-label="시연 참여자 전환">${state.members.map(p=>`<option value="${p.id}" ${p.id===state.profileId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="settings-links"><button type="button" data-action="preview">${icon('phone')} PC·안드로이드 디자인 미리보기</button><a href="/android" target="_blank" rel="noopener">${icon('phone')} 안드로이드 전용 UI 열기</a><button type="button" data-action="guide">${icon('file')} 이용 가이드</button><button type="button" data-action="notifications">${icon('bell')} 알림 확인</button><button type="button" data-action="storage-recovery">저장 데이터 복구</button><button type="button" data-action="storage-export">현재 데이터 내보내기</button><a href="/?practice=1">첫 캡슐 다시 연습하기</a><button type="button" data-action="reset">${icon('clock')} 데모 초기화</button></div><p class="settings-note">실제 로그인이 없는 로컬 데모입니다. 참여자를 바꿔 공동 확인 흐름을 시연할 수 있어요.</p>`,btn('close','닫기','primary'));}
function roomInfoDialog(){const m=meeting();openModal('채팅방 정보',`<div class="settings-profile">${groupAvatar(m,{state,esc})}<div><strong>${esc(m.title)}</strong><p>${esc(m.description)}</p></div></div><nav class="room-menu-views" aria-label="이 채팅방의 내용">${[['chat','chat','대화'],['minutes','file','회의록'],['result','calendar','확정 일정']].map(([v,ic,label])=>btn('view',icon(ic)+label+(view===v?' ✓':''),view===v?'active':'',`data-view="${v}"`)).join('')}</nav><p class="room-scope-note">이 메뉴에서는 현재 채팅방의 내용만 확인해요.</p><div class="form-section-label">대화 상대 <span>${m.memberIds.length}명</span></div><div class="participant-list">${m.memberIds.map(id=>`<div>${avatar(id,'small')}<span>${esc(memberName(state,id))}</span><small>${m.confirmations.includes(id)?'✓ 확인 완료':id===state.profileId?'나':'참여자'}</small></div>`).join('')}</div><div class="settings-links">${['open','review'].includes(m.status)&&state.profileId===(m.facilitatorId||m.memberIds[0])?btn('policy','참여 · 확인 대상 관리','outline')+btn('disposition','하위 캡슐 보류 · 취소','outline'):''}${btn('delegate',icon('branch')+' 대화를 하위 캡슐로 위임')}${btn('invite',icon('link')+' 초대 링크')}${btn('settings',icon('users')+' 시연 참여자 전환')}${m.parentId?btn('open',icon('back')+' 상위 회의로 돌아가기','',`data-id="${m.parentId}"`):''}</div>`,btn('close','닫기','primary'));}
const workflow=createWorkflowActions({repo,practice,esc,btn,field,openModal,modal,persist,render,toast,selectMeeting,tutorialEvent,selectFirst(){activeId=repo.get().meetings[0]?.id;view='chat';mobileScreen='list';}});
const extraAction=(...args)=>workflow.action(...args);
const extraSubmit=(...args)=>workflow.submit(...args);
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target||actionBusy)return;actionBusy=true;const action=target.dataset.action;let m=meeting();try{
 if(target.dataset.id&&['view','draft'].includes(action)){selectMeeting(target.dataset.id,target.dataset.view||'minutes');m=meeting();}
 if(['draft','confirm','delete-item','start-scheduled','restore-draft','tutorial-colleague','practice-example','switch-profile','sample'].includes(action))requireSaved();
 if(await extraAction(action,target,m))return;
 if(action==='toggle-list-search'){searchOpen=!searchOpen;if(!searchOpen)listSearch='';render();if(searchOpen)document.querySelector('#room-search')?.focus();return;}
 if(action==='clear-list-search'){listSearch='';render();document.querySelector('#room-search')?.focus();return;}
 if(action==='list-filter'){listFilter=target.dataset.filter;render();return;}
 if(action==='android-tab'){page=target.dataset.page;mobileScreen='list';const url=new URL(location.href);url.searchParams.delete('capsule');history.replaceState({screen:'list'},'',url);render();return;}
 if(action==='room-back'){if(history.state?.screen==='room'){history.back();}else{mobileScreen='list';const url=new URL(location.href);url.searchParams.delete('capsule');history.replaceState({screen:'list'},'',url);render();}return;}
 if(action==='preview'){window.open('/preview','_blank','noopener');return;}
 if(action==='settings'){settingsDialog();return;}
 if(action==='room-info'){roomInfoDialog();return;}
 if(action==='close'){modal.close();return;}
 if(action==='menu'){mobileMenu=!mobileMenu;render();return;}
 if(action==='create'){createDialog();return;}
 if(action==='delegate'){delegateDialog(target.dataset.anchor);return;}
 if(action==='clear-filter'){memberFilter='';creationMembers=new Set(state.members.map(p=>p.id));document.querySelector('#member-filter').value='';document.querySelector('#member-filter-results').innerHTML=renderMemberFilter();document.querySelector('#create-submit').innerHTML=`${creationMembers.size}명과 회의 시작 ${icon('arrow')}`;return;}
 if(action==='open'){if(modal.open)modal.close();selectMeeting(target.dataset.id,target.dataset.view||'chat');if(practice&&meeting()?.previousId===state.tutorial?.meetingId)tutorialEvent('next');await persist();render();return;}
 if(action==='workspace'){page=target.dataset.page;mobileMenu=false;if(page==='meeting'&&m&&!canRead(m,state.profileId)){const next=state.meetings.find(x=>canRead(x,state.profileId));if(next)activeId=next.id;}render();return;}
 if(action==='view'){view=target.dataset.view;if(modal.open)modal.close();render();return;}
 if(action==='chat'||action==='minutes'||action==='result'){view=action;render();return;}
 if(action==='draft'){extractDraft(state,m,{expectedRevision:m.revision});tutorialEvent('draft');await persist();view='minutes';render();toast('기존 편집을 보존하고 새 대화를 반영했어요.');return;}
 if(action==='confirm'){const done=confirmMeeting(state,m,{expectedRevision:Number(target.dataset.revision??m.revision)});if(done)tutorialEvent('confirmed');await persist();render();toast(done?'모든 참여자가 확인했어요. 확정한 결정을 다음으로 이었어요.':'이 버전의 확인을 남겼어요. 대기 중인 항목은 위에 표시돼요.');return;}
 if(action==='reopen'||action==='reopen-confirm'){resumeConversation(state,m);modal.close();view='chat';render();return;}
 if(action==='start-scheduled'){startScheduled(state,m);await persist();render();return;}
 if(action==='evidence'){evidenceDialog(target.dataset.type,target.dataset.id);return;}
 if(action==='edit-item'||action==='add-item'){editItemDialog(target.dataset.type,target.dataset.id);return;}
 if(action==='delete-item'){removeDraftItem(state,m,target.dataset.type,target.dataset.id,{expectedRevision:focusedSource?.revision??m.revision});modal.close();await persist();render();toast('항목을 제외했어요. 참여자 확인을 다시 받아요.');return;}
 if(action==='invite'){inviteDialog();return;}
 if(action==='copy-invite'){await copy(document.querySelector('#invite-url').value);return;}
 if(action==='switch-profile'){state.profileId=target.dataset.id;await persist();render();toast(memberName(state,state.profileId)+' 멤버로 시연해요.');return;}
 if(action==='month'){month=new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth()+Number(target.dataset.offset),1,12));render();return;}
 if(action==='ics'||action==='google'){const event=getConfirmedEvents(state,state.profileId).find(x=>x.id===target.dataset.id);if(!event)throw Error('이 일정이 확정된 채팅방의 참여자만 내보낼 수 있어요.');if(action==='ics'){const url=URL.createObjectURL(new Blob([makeICS(event)],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ITDA-'+event.text.replace(/[\\/:*?"<>|]/g,'')+'.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('확정 일정을 .ics 파일로 저장했어요.');}else{const stamp=d=>new Date(d).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z');const u=new URL('https://calendar.google.com/calendar/render');u.search=new URLSearchParams({action:'TEMPLATE',text:event.text,dates:stamp(event.at)+'/'+stamp(Date.parse(event.at)+3600000),location:event.location,details:'잇다에서 참여자 모두가 확정한 일정입니다.'});openModal('구글 캘린더에 추가',`<p class="form-note">${esc(event.text)}<br>${date(event.at)}<br>이름과 일정 정보가 구글 캘린더 작성 화면에 전달돼요. 저장은 새 화면에서 직접 완료해주세요.</p>`,`<a class="primary" href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">구글 캘린더 열기 ${icon('external')}</a>`);}return;}
 if(action==='share'){if(m.status!=='confirmed')throw Error('확정된 회의록만 공유할 수 있어요.');openModal('결정을 대화방으로 돌려보내요',`<div class="share-card"><div class="share-brand">${icon('link')} 잇다 ITDA <span>확정 회의록</span></div><h2>${esc(m.title)}</h2><p>참여자 ${m.confirmations.length}/${getConfirmationTargets(m).length}명 확인</p><pre>${esc(shareText(m))}</pre></div><p class="form-note">카카오 SDK는 연결하지 않았어요. 결과를 복사해서 카톡방에 붙여넣거나 기기의 공유 기능을 이용해주세요.</p>`,btn('share-native',icon('external')+' 기기로 공유','outline')+btn('copy-result','결과 복사하기','primary'));return;}
 if(action==='copy-result'){await copy(shareText(m));return;}
 if(action==='share-native'){if(navigator.share){try{await navigator.share({title:m.title,text:shareText(m)});}catch(error){if(error.name!=='AbortError')await copy(shareText(m));}}else await copy(shareText(m));return;}
 if(action==='notifications'){openModal('캡슐의 새로운 소식',state.notifications.length?`<div class="notification-list">${state.notifications.map(n=>`<article>${icon('calendar')}<div><strong>${esc(n.text)}</strong><small>${date(n.at)}</small></div></article>`).join('')}</div>`:empty('아직 새로운 소식이 없어요','확정된 일정이 생기면 여기에서 알려드려요.'),btn('close','확인','primary'));return;}
 if(action==='sample'){if(m.messages.length)throw Error('예시 대화는 빈 하위 캡슐에만 넣을 수 있어요.');['결정: 와플 4,000원 · 음료 2,500원','할 일: 가격표 제작 | 김민수 | 11월 4일'].forEach(text=>sendMessage(state,m,text));await persist();render();toast('시연용 예시를 넣었어요. 이제 회의록 초안을 만들어보세요.');return;}
 if(action==='reset'){openModal('데모를 처음으로 되돌릴까요?','<p class="form-note">이 브라우저에서 만든 캡슐, 대화, 회의록, 일정이 지워지고 기획서 속 축제 준비 시나리오로 돌아가요.</p>',btn('close','취소','quiet')+btn('reset-confirm','처음으로 되돌리기','primary'));return;}
 if(action==='reset-confirm'){const result=await repo.reset();if(!result.ok)throw Error(result.message);state=repo.get();if(!practice)addMessengerExamples(state);activeId=state.meetings[0]?.id;modal.close();await persist();render();toast('처음 시연 상태로 돌아왔어요.');return;}
 if(action==='guide'){openModal('방은 사라져도 일은 이어진다',`<div class="guide-steps">${[['멤버 소집','새 캡슐에서 “축제 준비팀 중 2학년”을 입력하고 멤버를 골라요.'],['하위 캡슐 위임','대화 중 ↳ 버튼으로 메시지와 담당 멤버를 선택해요.'],['결론 모으기','하위 캡슐의 회의록을 모두 확인하면 상위로 결론 카드가 합류해요.'],['근거 확인·확정','초안의 근거를 보고 “확인 필요”를 수정해요. 왼쪽 아래에서 참여자를 전환해 각각 확인해요.'],['캘린더로 잇기','전원 확인 후 일정·다음 캡슐·미결 안건이 자동으로 이어져요.']].map(([t,d],i)=>`<article><b>${i+1}</b><div><h3>${t}</h3><p>${d}</p></div></article>`).join('')}</div><div class="privacy-callout">${icon('shield')} 지금은 로그인·외부 AI·카카오 연동이 없는 로컬 데모예요. 멤버 전환은 실제 인증이 아니며, 내용은 이 브라우저에만 저장돼요.</div>`,btn('close','시작해볼게요 '+icon('arrow'),'primary'));return;}
 }catch(error){renderStorage();toast(error.message||'작업을 완료하지 못했어요.');}finally{actionBusy=false;}});
document.addEventListener('submit',async e=>{if(!['composer','create-form','delegate-form','item-form','policy-form','agenda-form','disposition-form','correction-form','recovery-form'].includes(e.target.getAttribute('id')))return;e.preventDefault();if(actionBusy)return;actionBusy=true;const form=e.target,data=Object.fromEntries(new FormData(form)),m=meeting();try{
 if(form.id!=='recovery-form')requireSaved();
 if(form.id==='composer'){sendMessage(state,m,data.message);tutorialEvent('message');markRead(m);clearComposer(activeId);await persist();render();document.querySelector('#composer textarea')?.focus();}
 if(form.id==='create-form'){const created=createMeeting(state,{title:data.title,description:data.description,memberIds:[...creationMembers]});selectMeeting(created.id);tutorialEvent('created',created.id);await persist();modal.close();render();toast('새 캡슐을 열었어요. 첫 이야기를 남겨보세요.');}
 if(form.id==='delegate-form'){const child=delegate(state,m,{title:data.title,messageIds:[...delegationSelection],memberIds:[...delegationMembers]});await persist();modal.close();render();toast(canRead(child,state.profileId)?'하위 캡슐을 열었어요. 결론은 상위로 합류해요.':'위임했어요. 담당 멤버로 전환하면 하위 캡슐을 볼 수 있어요.');}
 if(form.id==='item-form'){const {type,itemId,isNew}=focusedSource;const draftItem={id:itemId,text:data.text.trim(),evidenceIds:[...new FormData(form).getAll('evidence')]};if(type==='tasks'){draftItem.ownerId=data.ownerId;draftItem.dueAt=data.dueAt?new Date(data.dueAt+':00+09:00').toISOString():null;}if(type==='events'){draftItem.at=data.at?new Date(data.at+':00+09:00').toISOString():null;draftItem.hasTime=true;draftItem.location=data.location.trim();draftItem.kind=data.kind;draftItem.participantIds=new FormData(form).getAll('event-member');}const changed=updateDraftItem(state,m,type,draftItem,{expectedRevision:focusedSource.revision});if(changed)tutorialEvent('edited');await persist();modal.close();render();toast(changed?'수정한 새 버전의 확인을 받아요.':'변경이 없어 이전 확인을 유지했어요.');}
 await extraSubmit(form,data,m);
 }catch(error){renderStorage();toast(error.message||'입력한 내용을 다시 확인해주세요.');}finally{actionBusy=false;}});
document.addEventListener('keydown',e=>{if(e.target.matches('#composer textarea')&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();e.target.form.requestSubmit();}});
document.addEventListener('input',e=>{if(e.target.id==='room-search'){listSearch=e.target.value;const template=document.createElement('template');template.innerHTML=renderRoomList(layoutContext());document.querySelector('.room-list-rows').innerHTML=template.content.querySelector('.room-list-rows').innerHTML;}if(e.target.id==='message-search'){search=e.target.value;const el=document.querySelector('#messages');el.innerHTML=`<div class="chat-date"><span>${search?'검색 결과':'대화'}</span></div>`+meeting().messages.filter(x=>x.text.toLowerCase().includes(search.toLowerCase())).map(x=>renderMessage(x,meeting())).join('');if(!el.querySelector('.message'))el.innerHTML+=empty('검색 결과가 없어요','다른 단어로 찾아보세요.');}if(e.target.id==='member-filter'){memberFilter=e.target.value;creationMembers=new Set(parseMemberFilter(memberFilter,state.members).members.map(p=>p.id));creationMembers.add(state.profileId);document.querySelector('#member-filter-results').innerHTML=renderMemberFilter();document.querySelector('#create-submit').innerHTML=`${creationMembers.size}명과 회의 시작 ${icon('arrow')}`;}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='profile-select'){if(actionBusy)return;actionBusy=true;try{state.profileId=t.value;modal.close();markRead(meeting());await persist();render();}catch(error){toast(error.message);}finally{actionBusy=false;}}if(t.name==='create-member'){t.checked?creationMembers.add(t.value):creationMembers.delete(t.value);document.querySelector('#create-submit').innerHTML=`${creationMembers.size}명과 회의 시작 ${icon('arrow')}`;}if(t.name==='delegate-message'){t.checked?delegationSelection.add(t.value):delegationSelection.delete(t.value);document.querySelector('#selected-message-count').textContent=delegationSelection.size+'개 선택';}if(t.name==='delegate-member'){t.checked?delegationMembers.add(t.value):delegationMembers.delete(t.value);}});
let composing=false;
document.addEventListener('compositionstart',()=>{composing=true;});
document.addEventListener('compositionend',()=>{composing=false;});
async function checkScheduled(){if(actionBusy||composing||modal.open||repo.status.kind!=='ready')return;actionBusy=true;try{if(activateScheduled(state)){await persist();render();toast('예약한 캡슐이 열렸어요.');}}catch(error){toast(error.message);}finally{actionBusy=false;}}
setInterval(checkScheduled,30000);
mobileQuery.addEventListener('change',()=>{if(!composing)render();});
window.addEventListener('popstate',()=>{if(actionBusy)return;const id=new URLSearchParams(location.search).get('capsule');if(id&&state.meetings.some(m=>m.id===id)){activeId=id;page='meeting';mobileScreen='room';view='chat';markRead(meeting());}else{mobileScreen='list';page='meeting';}render();});
window.addEventListener('beforeunload',event=>{if(['unsaved','conflict','recovery','unavailable'].includes(repo.status.kind)){event.preventDefault();event.returnValue='';}});
render();await checkScheduled();if(repo.warning)toast(repo.warning);
